<body>
<h1>🐍 Snake – שליטה במגע</h1>
<canvas id="gameCanvas" width="400" height="400"></canvas>
<div id="score">נקודות: 0</div>

<div class="controls">
 <button class="ctrl-btn" id="upBtn">▲</button>
 <div></div>
 <button class="ctrl-btn" id="rightBtn">▶</button>
 <button class="ctrl-btn" id="leftBtn">◀</button>
 <div></div>
 <button class="ctrl-btn" id="downBtn">▼</button>
</div>

<div id="overlay"></div>
<button id="restartBtn" style="display:none;">התחל מחדש</button>

<script>
(() => {
 const canvas = document.getElementById('gameCanvas');
 const ctx = canvas.getContext('2d');
 const overlay = document.getElementById('overlay');
 const scoreEl = document.getElementById('score');
 const restartBtn = document.getElementById('restartBtn');

 const btnUp = document.getElementById('upBtn');
 const btnDown = document.getElementById('downBtn');
 const btnLeft = document.getElementById('leftBtn');
 const btnRight = document.getElementById('rightBtn');

 const cfg = {rows:20, cols:20, cell:20, speed:120};

 let snake, food, dir, nextDir, score, loop, gameOver;

 const init = () => {
 snake = [{x:9,y:9}];
 dir = {x:1,y:0};
 nextDir = dir;
 placeFood();
 score = 0;
 gameOver = false;
 scoreEl.textContent = 'נקודות: 0';
 overlay.classList.remove('show');
 restartBtn.style.display='none';
 clearInterval(loop);
 loop = setInterval(tick, cfg.speed);
 };

 const placeFood = () => {
 let ok = false;
 while(!ok){
 food = {x:Math.floor(Math.random()*cfg.cols), y:Math.floor(Math.random()*cfg.rows)};
 ok = !snake.some(s=>s.x===food.x && s.y===food.y);
 }
 };

 const drawCell = (x,y,color)=>{ctx.fillStyle=color;ctx.fillRect(x*cfg.cell,y*cfg.cell,cfg.cell,cfg.cell);};

 const render = () => {
 ctx.clearRect(0,0,canvas.width,canvas.height);
 //grid
 ctx.strokeStyle='#3a3a55';
 for(let i=0;i<=cfg.cols;i++){
 ctx.beginPath();ctx.moveTo(i*cfg.cell,0);ctx.lineTo(i*cfg.cell,canvas.height);ctx.stroke();
 }
 for(let i=0;i<=cfg.rows;i++){
 ctx.beginPath();ctx.moveTo(0,i*cfg.cell);ctx.lineTo(canvas.width,i*cfg.cell);ctx.stroke();
 }
 //snake
 snake.forEach((s,i)=>drawCell(s.x,s.y,i===0?'var(--snake-head)':'var(--snake-body)'));
 //food
 drawCell(food.x,food.y,'var(--food)');
 };

 const tick = () => {
 // שינוי כיוון רק אם אינו הפוך
 if(!((nextDir.x===-dir.x && nextDir.y===0)||(nextDir.y===-dir.y && nextDir.x===0))){
 dir = nextDir;
 }
 const head = {x:(snake[0].x+dir.x+cfg.cols)%cfg.cols,
 y:(snake[0].y+dir.y+cfg.rows)%cfg.rows};

 // התנגשות בעצמו
 if(snake.some(s=>s.x===head.x && s.y===head.y)){
 endGame();return;
 }

 snake.unshift(head);
 if(head.x===food.x && head.y===food.y){
 score++;scoreEl.textContent=`נקודות: ${score}`;placeFood();
 }else{
 snake.pop();
 }
 render();
 };

 const endGame = () => {
 clearInterval(loop);
 gameOver=true;
 overlay.textContent=`המשחק נגמר! ניקוד: ${score}`;
 overlay.classList.add('show');
 restartBtn.style.display='inline-block';
 };

 // שליטה במגע
 const setDirection = d=>{nextDir=d;};
 btnUp.addEventListener('click',()=>setDirection({x:0,y:-1}));
 btnDown.addEventListener('click',()=>setDirection({x:0,y:1}));
 btnLeft.addEventListener('click',()=>setDirection({x:-1,y:0}));
 btnRight.addEventListener('click',()=>setDirection({x:1,y:0}));

 restartBtn.addEventListener('click',init);
 // אפשרות לשימוש במקשים גם כן (לא חובה)
 document.addEventListener('keydown',e=>{
 const map={ArrowUp:{x:0,y:-1},ArrowDown:{x:0,y:1},
 ArrowLeft:{x:-1,y:0},ArrowRight:{x:1,y:0},
 w:{x:0,y:-1},s:{x:0,y:1},a:{x:-1,y:0},d:{x:1,y:0}};
 if(map[e.key] && !gameOver) setDirection(map[e.key]);
 });

 init();
})();
</script>
