```javascript
// file: script.js
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const startBtn = document.getElementById('startBtn');
const restartBtn = document.getElementById('restartBtn');
const menu = document.getElementById('menu');
const gameContainer = document.getElementById('gameContainer');
const difficultySelect = document.getElementById('difficulty');
const scoreEl = document.getElementById('score');
const controlButtons = document.querySelectorAll('.control-btn');

const CELL_SIZE = 20;
const COLS = canvas.width / CELL_SIZE;
const ROWS = canvas.height / CELL_SIZE;

let snake, food, direction, nextDirection, score, speed, gameLoop;

// הגדרות מהירות לפי רמת קושי
const SPEEDS = {
 easy: 150,
 medium: 100,
 hard: 60
};

function initGame() {
 snake = [{ x: Math.floor(COLS / 2), y: Math.floor(ROWS / 2) }];
 direction = { x: 0, y: -1 }; // מתחילים למעלה
 nextDirection = direction;
 placeFood();
 score = 0;
 updateScore();
 speed = SPEEDS[difficultySelect.value];
 clearInterval(gameLoop);
 gameLoop = setInterval(gameTick, speed);
}

function placeFood() {
 let valid = false;
 while (!valid) {
 food = {
 x: Math.floor(Math.random() * COLS),
 y: Math.floor(Math.random() * ROWS)
 };
 valid = !snake.some(segment => segment.x === food.x && segment.y === food.y);
 }
}

function gameTick() {
 // עדכון כיוון לפני תזוזה
 if (Math.abs(nextDirection.x) !== Math.abs(direction.x) ||
 Math.abs(nextDirection.y) !== Math.abs(direction.y)) {
 direction = nextDirection;
 }

 const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

 // בדיקת גבולות
 if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS) {
 endGame();
 return;
 }

 // בדיקת התנגשות בעצמו
 if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
 endGame();
 return;
 }

 snake.unshift(head);

 // אכילת אוכל
 if (head.x === food.x && head.y === food.y) {
 score += 10;
 updateScore();
 placeFood();
 } else {
 snake.pop();
 }

 draw();
}

function draw() {
 ctx.clearRect(0, 0, canvas.width, canvas.height);

 // צביעת הרקע של הרשת (אופציונלי)
 ctx.fillStyle = '#001a00';
 ctx.fillRect(0, 0, canvas.width, canvas.height);

 // ציור אוכל
 ctx.fillStyle = '#ff4040';
 ctx.fillRect(food.x * CELL_SIZE, food.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);

 // ציור נחש
 ctx.fillStyle = '#00ff00';
 snake.forEach((segment, index) => {
 ctx.fillStyle = index === 0 ? '#aaffaa' : '#00ff00';
 ctx.fillRect(segment.x * CELL_SIZE, segment.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
 });
}

function updateScore() {
 scoreEl.textContent = `Score: ${score}`;
}

function endGame() {
 clearInterval(gameLoop);
 alert(`המשחק נגמר! ניקוד סופי: ${score}`);
 menu.style.display = 'block';
 gameContainer.style.display = 'none';
}

// שליטה במקלדת
document.addEventListener('keydown', e => {
 switch (e.key) {
 case 'ArrowUp':
 case 'w':
 nextDirection = { x: 0, y: -1 };
 break;
 case 'ArrowDown':
 case 's':
 nextDirection = { x: 0, y: 1 };
 break;
 case 'ArrowLeft':
 case 'a':
 nextDirection = { x: -1, y: 0 };
 break;
 case 'ArrowRight':
 case 'd':
 nextDirection = { x: 1, y: 0 };
 break;
 }
});

// שליטה בכפתורים
controlButtons.forEach(btn => {
 btn.addEventListener('click', () => {
 const dir = btn.dataset.dir;
 switch (dir) {
 case 'up':
 nextDirection = { x: 0, y: -1 };
 break;
 case 'down':
 nextDirection = { x: 0, y: 1 };
 break;
 case 'left':
 nextDirection = { x: -1, y: 0 };
 break;
 case 'right':
 nextDirection = { x: 1, y: 0 };
 break;
 }
 });
});

startBtn.addEventListener('click', () => {
 menu.style.display = 'none';
 gameContainer.style.display = 'block';
 initGame();
});

restartBtn.addEventListener('click', () => {
 initGame();
});
